-- E00-T01: the tenant foundation. The table definitions are generated by drizzle-kit from
-- src/modules/*/schema.ts. The extension, current_clinic_id(), Row-Level Security policies,
-- grants and the temporary-table revoke are hand-written: drizzle-kit does not manage them.

-- btree_gist lets an exclusion constraint combine "same clinic and provider" with "overlapping
-- time", which is how double booking is blocked (D-020, E01).
CREATE EXTENSION IF NOT EXISTS btree_gist;
--> statement-breakpoint
-- The clinic of the current transaction, set by withTenant() (src/db/tenant.ts). NULL when no
-- clinic is set, so tenant policies match no rows. Once a session has set the value, an unset
-- value reads as '' rather than NULL, hence nullif.
CREATE FUNCTION current_clinic_id() RETURNS uuid
  LANGUAGE sql STABLE PARALLEL SAFE
  AS $$ SELECT nullif(current_setting('app.clinic_id', true), '')::uuid $$;
--> statement-breakpoint
CREATE TABLE "audit_log" (
	"id" uuid PRIMARY KEY NOT NULL,
	"clinic_id" uuid NOT NULL,
	"at" timestamp with time zone NOT NULL,
	"actor_type" text NOT NULL,
	"actor_id" text,
	"action" text NOT NULL,
	"entity_type" text,
	"entity_id" text,
	"metadata" jsonb DEFAULT '{}'::jsonb NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "audit_log_clinic_id_id_key" UNIQUE("clinic_id","id"),
	CONSTRAINT "audit_log_actor_type_check" CHECK ("audit_log"."actor_type" in ('user', 'patient_link', 'system')),
	CONSTRAINT "audit_log_metadata_check" CHECK (jsonb_typeof("audit_log"."metadata") = 'object')
);
--> statement-breakpoint
CREATE TABLE "clinics" (
	"id" uuid PRIMARY KEY NOT NULL,
	"name" text NOT NULL,
	"timezone" text NOT NULL,
	"locale" text NOT NULL,
	"currency" text NOT NULL,
	"default_country" text NOT NULL,
	"phone" text,
	"address" text,
	"email" text,
	"status" text DEFAULT 'active' NOT NULL,
	"settings" jsonb DEFAULT '{}'::jsonb NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "clinics_status_check" CHECK ("clinics"."status" in ('active', 'paused')),
	CONSTRAINT "clinics_currency_check" CHECK ("clinics"."currency" ~ '^[A-Z]{3}$'),
	CONSTRAINT "clinics_default_country_check" CHECK ("clinics"."default_country" ~ '^[A-Z]{2}$'),
	CONSTRAINT "clinics_phone_check" CHECK ("clinics"."phone" ~ '^\+[1-9][0-9]{1,14}$'),
	CONSTRAINT "clinics_email_check" CHECK ("clinics"."email" = lower("clinics"."email")),
	CONSTRAINT "clinics_settings_check" CHECK (jsonb_typeof("clinics"."settings") = 'object')
);
--> statement-breakpoint
ALTER TABLE "audit_log" ADD CONSTRAINT "audit_log_clinic_id_clinics_id_fk" FOREIGN KEY ("clinic_id") REFERENCES "public"."clinics"("id") ON DELETE no action ON UPDATE no action;--> statement-breakpoint
CREATE INDEX "audit_log_clinic_id_at_idx" ON "audit_log" USING btree ("clinic_id","at");
--> statement-breakpoint
-- Row-Level Security: a row is visible and writable only inside its own clinic's transaction.
-- clinics is the tenant itself, so its policy compares id.
ALTER TABLE "clinics" ENABLE ROW LEVEL SECURITY;
--> statement-breakpoint
CREATE POLICY "clinics_tenant_isolation" ON "clinics"
  USING ("id" = current_clinic_id())
  WITH CHECK ("id" = current_clinic_id());
--> statement-breakpoint
ALTER TABLE "audit_log" ENABLE ROW LEVEL SECURITY;
--> statement-breakpoint
CREATE POLICY "audit_log_tenant_isolation" ON "audit_log"
  USING ("clinic_id" = current_clinic_id())
  WITH CHECK ("clinic_id" = current_clinic_id());
--> statement-breakpoint
-- Grants for the app role (chairside_app). It owns nothing, so it cannot change the schema.
-- Clinics are created by the operator script (E00-T05), never deleted by the app.
-- The audit log is append-only: no UPDATE, no DELETE, no TRUNCATE.
GRANT USAGE ON SCHEMA public TO chairside_app;
--> statement-breakpoint
GRANT SELECT, UPDATE ON "clinics" TO chairside_app;
--> statement-breakpoint
GRANT SELECT, INSERT ON "audit_log" TO chairside_app;
--> statement-breakpoint
-- No temporary tables for the app role. PostgreSQL lets every role (PUBLIC) create them by
-- default. A temporary table outlives its transaction and is found before the real table of the
-- same name, so it could hand one clinic's rows to the next clinic on that pooled connection.
-- The check fails this migration if the revoke did not take effect (for example when the
-- migration role does not own the database), instead of leaving the hole open silently.
DO $$
BEGIN
  EXECUTE format('REVOKE TEMPORARY ON DATABASE %I FROM PUBLIC', current_database());
  IF has_database_privilege('chairside_app', current_database(), 'TEMPORARY') THEN
    RAISE EXCEPTION 'chairside_app can still create temporary tables in database %',
      current_database();
  END IF;
END
$$;
